# Separate physical per-set market exposure and observed-default closeout checks.
counterparty_exposure_backtest<-function(forecasts,observations,quantile_levels,design,uncertainty,cluster_resamples=NULL,confidence_level=.95,context=NULL){
 d<-.vb_design(design,context);currency<-.vb_string(d$currency,'design currency');rows<-.vr_rows(forecasts,'forecasts');observed<-.vr_rows(observations,'observations');unwrap<-function(row){for(key in c('netting_paths','collateral_paths'))if(inherits(row[[key]],'CalcResult'))row[[key]]<-row[[key]]$value;row};rows<-lapply(rows,unwrap);observed<-lapply(observed,unwrap);rows<-.vb_records(rows,d);.ex_ids(lapply(observed,function(r)r$prediction_id),'observation prediction IDs',empty=TRUE);obs<-setNames(observed,vapply(observed,function(r)r$prediction_id,character(1)));if(!all(names(obs)%in%vapply(rows,function(r)r$prediction_id,character(1)))).cr_error('CCR_VALIDATION_ALIGNMENT','Observation references unknown forecast');q<-.vb_vec(quantile_levels,'quantile_levels');if(!length(q)||any(q<=0|q>=1)||anyDuplicated(q)).cr_error('CCR_VALIDATION_QUANTILES','Distinct interior quantiles required');q<-sort(q);n<-length(rows);p<-y<-cp<-cy<-rep(0,n);weights<-rep(1,n);eligible<-celigible<-rep(FALSE,n);thresholds<-tails<-matrix(0,n,length(q));exclusions<-traces<-violations<-closeout_traces<-list();cutoff<-.cr_data_date(d$evaluation_cutoff,'evaluation cutoff');issue<-function(identity,code,detail)violations[[length(violations)+1]]<<-list(prediction_id=identity,code=code,detail=detail);same<-function(a,b)identical(.cr_hash(a),.cr_hash(b));near<-function(a,b)abs(a-b)<=1e-12+1e-10*abs(b)
 agreement<-function(artifact,row){found<-Filter(function(a)a$netting_set_id==row$netting_set_id,artifact$netting_agreements);if(length(found)!=1||found[[1]]$counterparty_id!=row$counterparty_id).cr_error('CCR_VALIDATION_SCOPE','Counterparty/set must match frozen agreement');found[[1]]}
 artifacts<-function(row,forecast){net<-.cr_ead_artifact(row$netting_paths,'NETTING_PATHS');if(net$as_of!=forecast$as_of||net$currency!=currency).cr_error('CCR_VALIDATION_ARTIFACT','Snapshot/currency differs from forecast origin');agreement(net,forecast);coll<-NULL;if(forecast$exposure_target=='COLLATERALIZED'){coll<-.cr_ead_artifact(row$collateral_paths,'COLLATERAL_PATHS');if(coll$netting_artifact_hash!=net$artifact_hash).cr_error('CCR_VALIDATION_BINDING','Collateral artifact does not bind matching netting paths')}else if(!is.null(row$collateral_paths)).cr_error('CCR_VALIDATION_TARGET','Uncollateralized target cannot include collateral');list(net=net,coll=coll)}
 for(i in seq_along(rows)){row<-rows[[i]];identity<-row$prediction_id;weights[i]<-.vb_number(if(is.null(row$weight))1 else row$weight,'evaluation weight',0);for(key in c('counterparty_id','netting_set_id','legal_version')).vb_string(row[[key]],key);if(!row$exposure_target%in%c('UNCOLLATERALIZED','COLLATERALIZED')).cr_error('CCR_VALIDATION_TARGET','Explicit collateralization target required');if(row$exposure_target=='COLLATERALIZED').vb_string(row$csa_version,'csa_version');art<-artifacts(row,row);net<-art$net;coll<-art$coll;ag<-agreement(net,row);if(ag$known_at>row$forecast_known_at).cr_error('CCR_VALIDATION_LOOKAHEAD','Agreement unavailable at forecast');if(!is.null(coll)&&any(vapply(coll$margin_policies,function(a)a$known_at>row$forecast_known_at,logical(1)))).cr_error('CCR_VALIDATION_LOOKAHEAD','CSA unavailable at forecast');path_ids<-as.character(unlist(net$path_ids,use.names=FALSE));pw<-row$path_weights;if(is.null(pw)){w<-rep(1/length(path_ids),length(path_ids))}else{pw<-.ex_object(pw,'path_weights');if(!setequal(names(pw),path_ids)).cr_error('CCR_VALIDATION_PATHS','Weights must cover exact scenario IDs');w<-vapply(path_ids,function(k).vb_number(pw[[k]],'path weight',0),numeric(1));if(!any(w>0)).cr_error('CCR_VALIDATION_PATHS','Positive scenario weight required');w<-w/max(w);w<-w/sum(w)};source<-if(is.null(coll))net else coll;field<-if(is.null(coll))'positive_exposure'else'residual_exposure';selected<-Filter(function(r)r$netting_set_id==row$netting_set_id&&r$date==row$horizon_end,source$paths);selected<-setNames(selected,vapply(selected,function(r)r$path_id,character(1)));if(!setequal(names(selected),path_ids)).cr_error('CCR_VALIDATION_HORIZON','Exact common scenario/horizon/set slice required');x<-vapply(path_ids,function(k).vb_number(selected[[k]][[field]],'exposure sample',0),numeric(1));p[i]<-sum(w*x);ord<-order(x,seq_along(x));cdf<-cumsum(w[ord]);cdf[length(cdf)]<-1;for(j in seq_along(q)){thresholds[i,j]<-x[ord[which(cdf>=q[j])[1]]];tails[i,j]<-sum(w*(x>thresholds[i,j]))};actual<-obs[[identity]];reason<-NULL;recomputed<-NULL;on<-oc<-NULL;valid_contract<-TRUE
 if(.cr_data_date(row$horizon_end,'horizon_end')>cutoff){reason<-'IMMATURE_HORIZON'}else if(is.null(actual)||identical(actual$observation_status,'CENSORED')){reason<-'EXPOSURE_NOT_OBSERVED'}else{if(!identical(actual$observation_status,'OBSERVED')).cr_error('CCR_VALIDATION_OBSERVATION','Explicit OBSERVED or CENSORED required');at<-.cr_data_date(actual$observed_at,'observed_at');known<-.cr_data_date(actual$known_at,'observation known_at');if(known<at||actual$observed_at!=row$horizon_end).cr_error('CCR_VALIDATION_ALIGNMENT','Exact endpoint with subsequent knowledge required');if(known>cutoff){reason<-'EXPOSURE_NOT_YET_KNOWN'}else{oa<-artifacts(actual,row);on<-oa$net;oc<-oa$coll;if(!same(on$netting_agreements,net$netting_agreements)||!identical(actual$legal_version,row$legal_version)){issue(identity,'NETTING_CONTRACT_CHANGED','Observed legal membership/version differs from frozen forecast');valid_contract<-FALSE};if(!is.null(coll)&&(!same(oc$margin_policies,coll$margin_policies)||!identical(actual$csa_version,row$csa_version))){issue(identity,'CSA_CONTRACT_CHANGED','Observed margin/posted-claim contract/version differs from frozen forecast');valid_contract<-FALSE};os<-if(is.null(oc))on else oc;candidates<-Filter(function(r)identical(r$path_id,actual$observed_path_id)&&r$date==row$horizon_end&&r$netting_set_id==row$netting_set_id,os$paths);if(length(candidates)!=1).cr_error('CCR_VALIDATION_ALIGNMENT','Unique actual path/set/endpoint required');recomputed<-.vb_number(candidates[[1]][[field]],'observed exposure',0);reported<-.vb_number(actual$reported_exposure,'reported exposure',0);if(!near(reported,recomputed)){issue(identity,'ILLEGAL_OFFSET_OR_EXPOSURE_RECONCILIATION','Reported exposure differs from exact per-set collateral/netting exposure');valid_contract<-FALSE};y[i]<-recomputed;if(!valid_contract)reason<-'CONTRACT_OR_EXPOSURE_RECONCILIATION'else if(weights[i]==0)reason<-'ZERO_EVALUATION_WEIGHT'else eligible[i]<-TRUE}}
 if(!is.null(reason))exclusions[[length(exclusions)+1]]<-list(prediction_id=identity,reason=reason);traces[[length(traces)+1]]<-list(prediction_id=identity,counterparty_id=row$counterparty_id,netting_set_id=row$netting_set_id,forecast_netting_hash=net$artifact_hash,forecast_collateral_hash=if(is.null(coll))NULL else coll$artifact_hash,forecast_mean=p[i],quantiles=lapply(seq_along(q),function(j)list(level=q[j],value=thresholds[i,j],model_strict_tail_probability=tails[i,j])),recomputed_observed_exposure=recomputed,eligible=eligible[i]);ctr<-list(prediction_id=identity,applicability='NOT_APPLICABLE',reason='NO_OBSERVED_DEFAULT_CLOSEOUT',predicted_mean=NULL,observed_exposure=NULL,simulated_default_paths=0);forecast_events<-row$default_events
 if(length(forecast_events)){sampling<-.ex_object(row$default_sampling_contract,'default_sampling_contract');.vb_string(sampling$reference,'default sampling reference');if(!identical(sampling$mode,'JOINT_SIMULATED_PATHS')||.cr_data_date(sampling$known_at,'default sampling known_at')>.cr_data_date(row$forecast_known_at,'forecast_known_at')).cr_error('CCR_VALIDATION_DEFAULT_SAMPLING','Historically frozen joint default-path contract required');if(is.null(coll)).cr_error('CCR_VALIDATION_CLOSEOUT','Explicit collateral artifact required for closeout');flows<-if(is.null(row$intermediate_cashflows))list()else row$intermediate_cashflows;simulated<-closeout_exposure_at_default(net,coll,forecast_events,flows,freeze_timing=row$freeze_timing,cashflow_convention=row$cashflow_convention)$value$closeouts;simulated<-Filter(function(r)r$netting_set_id==row$netting_set_id&&row$as_of<=r$default_date&&r$default_date<=row$horizon_end,simulated);sw<-vapply(simulated,function(r)unname(w[match(r$path_id,path_ids)]),numeric(1));sx<-vapply(simulated,function(r)r$closeout_exposure,numeric(1));ctr$simulated_default_paths<-length(simulated);if(length(sw)&&sum(sw)>0){cp[i]<-sum(sw/sum(sw)*sx);ctr$predicted_mean<-cp[i]}
 if(!is.null(actual)&&!is.null(actual$closeout_event)){event<-actual$closeout_event;end<-.cr_data_date(event$closeout_date,'closeout_date');available<-.cr_data_date(actual$closeout_known_at,'closeout_known_at');if(available<end||!identical(event$path_id,actual$observed_path_id)||!identical(event$netting_set_id,row$netting_set_id)||is.null(event$default_date)||event$default_date<row$as_of||event$default_date>row$horizon_end).cr_error('CCR_VALIDATION_CLOSEOUT','Aligned dated observed default and closeout required');if(end>cutoff||available>cutoff||.cr_data_date(row$horizon_end,'horizon_end')>cutoff){ctr$reason<-'IMMATURE_OR_UNKNOWN_DEFAULT_CLOSEOUT'}else if(!valid_contract){ctr$reason<-'UNVERIFIED_OBSERVED_CONTRACT'}else if(!length(sw)||sum(sw)==0){ctr$reason<-'NO_SIMULATED_DEFAULT_SUPPORT'}else{if(is.null(on)){oa<-artifacts(actual,row);on<-oa$net;oc<-oa$coll;valid_contract<-same(on$netting_agreements,net$netting_agreements)&&identical(actual$legal_version,row$legal_version)&&same(oc$margin_policies,coll$margin_policies)&&identical(actual$csa_version,row$csa_version);if(!valid_contract){issue(identity,'CLOSEOUT_CONTRACT_CHANGED','Observed default closeout legal/CSA contract differs from frozen forecast');ctr$reason<-'UNVERIFIED_OBSERVED_CONTRACT';closeout_traces[[length(closeout_traces)+1]]<-ctr;next}};flows<-if(is.null(actual$intermediate_cashflows))list()else actual$intermediate_cashflows;closed<-closeout_exposure_at_default(on,oc,list(event),flows,freeze_timing=row$freeze_timing,cashflow_convention=row$cashflow_convention)$value$closeouts[[1]];cy[i]<-closed$closeout_exposure;reported<-.vb_number(actual$reported_closeout_exposure,'reported closeout exposure',0);if(!near(reported,cy[i])){issue(identity,'CLOSEOUT_RECONCILIATION','Reported closeout differs from frozen-units/date-aware calculation');ctr$reason<-'CLOSEOUT_RECONCILIATION'}else if(weights[i]==0){ctr$reason<-'ZERO_EVALUATION_WEIGHT'}else{celigible[i]<-TRUE;ctr$applicability<-'APPLICABLE';ctr['reason']<-list(NULL);ctr$observed_exposure<-cy[i];ctr$closeout_details<-closed}}}
 }else if(!is.null(actual)&&!is.null(actual$closeout_event))ctr$reason<-'NO_FROZEN_DEFAULT_FORECAST';closeout_traces[[length(closeout_traces)+1]]<-ctr}
 calculate<-function(draw){ew<-weights*draw*eligible;total<-sum(ew);quant<-lapply(seq_along(q),function(j){pinball<-ifelse(y>=thresholds[,j],q[j]*(y-thresholds[,j]),(1-q[j])*(thresholds[,j]-y));list(level=q[j],exception_rate=if(total==0)NULL else sum(ew*(y>thresholds[,j]))/total,nominal_tail_probability=1-q[j],mean_model_strict_tail_probability=if(total==0)NULL else sum(ew*tails[,j])/total,pinball_loss=if(total==0)NULL else sum(ew*pinball)/total,applicability=if(total>0)'APPLICABLE'else'NOT_APPLICABLE')});list(market_exposure=.vb_errors(p,y,ew),quantile_exceptions=quant,conditional_default_closeout=.vb_errors(cp,cy,weights*draw*celigible))};metrics<-calculate(rep(1,n));draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);samples<-if(is.null(draws))NULL else lapply(draws,function(draw){m<-calculate(draw);sample<-list();for(kind in c('market_exposure','conditional_default_closeout'))for(metric in c('bias','rmse'))sample[paste(kind,metric,sep='/')]<-list(m[[kind]][[metric]]);for(j in seq_along(m$quantile_exceptions))for(key in c('exception_rate','pinball_loss'))sample[paste0('quantile_',j-1,'/',key)]<-list(m$quantile_exceptions[[j]][[key]]);sample});diagnostics<-list(forecast_traces=traces,closeout_traces=closeout_traces,reconciliation_violations=violations,observation_fingerprint=.cr_hash(observed),quantile_convention='WEIGHTED_EMPIRICAL_INVERSE_CDF_LEFT',exception_convention='STRICTLY_GREATER_THAN_QUANTILE',cross_set_offset_permitted=FALSE,rare_default_loss_assessed=FALSE,closeout_estimand='EXPOSURE_CONDITIONAL_ON_SIMULATED_DEFAULT_WITHIN_FORECAST_HORIZON',path_sampling_uncertainty_assessed=FALSE);result<-.vb_result('counterparty_exposure_backtest',metrics,d,rows,exclusions,.vb_bands(samples,confidence_level),context,diagnostics,currency);result$value$diagnostics$closeout_included_count<-sum(celigible);if(any(celigible)){result$value$applicability<-'APPLICABLE';result$value['reason']<-list(NULL)};if(length(violations))result$value$decision<-list(status='FAIL',rule='FROZEN_CONTRACT_AND_EXPOSURE_RECONCILIATION');result
}
